        (2, 1, "Bài 2: Nguyên tố hóa học & Đồng vị", "Số hiệu nguyên tử Z, số khối A = Z + N. Đồng vị là các nguyên tử cùng Z khác A. Nguyên tử khối trung bình.", ["A = Z + N", "A_tb = (a×A₁ + b×A₂) / 100"], ["¹H, ²H (Đơteri), ³H (Triti) là 3 đồng vị của Hydro"], ["Kí hiệu nguyên tử: ᴬ_Z X."], "Nguyên tử có 17 proton và 18 neutron thì số khối A bằng bao nhiêu?", "A = 17 + 18 = 35.", ["CHLORINE", "SODIUM"]),
        (3, 1, "Bài 3: Cấu trúc lớp vỏ electron nguyên tử", "Mô hình Rutherford-Bohr và orbital nguyên tử (AO). Cấu hình electron theo mức năng lượng.", ["Số e tối đa lớp n = 2n² (n ≤ 4)", "Phân lớp: s (2e), p (6e), d (10e), f (14e)", "Thứ tự: 1s 2s 2p 3s 3p 4s 3d 4p..."], ["Na (Z=11): 1s² 2s² 2p⁶ 3s¹", "Fe (Z=26): 1s² 2s² 2p⁶ 3s² 3p⁶ 3d⁶ 4s²"], ["Quy tắc Hund và nguyên lí Pauli xác định phân bố spin electron."], "Viết cấu hình e của Cl (Z = 17) và xác định số e lớp ngoài cùng?", "1s² 2s² 2p⁶ 3s² 3p⁵. Có 7 electron ở lớp ngoài cùng.", ["CHLORINE", "SODIUM"]),
        (4, 1, "Bài 4: Ôn tập chương 1", "Tổng kết thành phần nguyên tử, đồng vị, cấu hình electron và orbital AO.", ["Ôn tập Z, A, Cấu hình e"], ["1s² 2s² 2p⁶ 3s² 3p⁶"], ["Củng cố bài tập xác định vị trí nguyên tố theo cấu hình e."], "Nguyên tố có cấu hình e kết thúc ở 3d5 4s1 là nguyên tố nào?", "Là Crom (Cr, Z = 24).", ["Fe", "Al"]),
        (5, 2, "Bài 5: Cấu tạo của Bảng tuần hoàn", "Nguyên tắc sắp xếp theo Z tăng dần. Cấu tạo gồm Ô nguyên tố, Chu kì (7 chu kì) và Nhóm (8 nhóm A, 8 nhóm B).", ["STT ô = Z", "STT chu kì = Số lớp electron", "STT nhóm A = Số e hóa trị (lớp ngoài cùng)"], ["Khối nguyên tố s, p, d, f"], ["Phân biệt nguyên tố s, p (nhóm A) và nguyên tố d, f (nhóm B)."], "Nguyên tố có cấu hình [Ne] 3s2 3p4 ở chu kì mấy, nhóm mấy?", "Ở chu kì 3, nhóm VIA.", ["SO2", "OXYGEN"]),
        (6, 2, "Bài 6: Xu hướng biến đổi tính chất trong BTH", "Quy luật biến đổi bán kính nguyên tử, độ âm điện, tính kim loại và tính phi kim trong chu kì và nhóm.", ["Trong chu kì (Trái → Phải): R giảm, Độ âm điện tăng, Tính phi kim tăng, Kim loại giảm", "Trong nhóm A (Trên → Dưới): R tăng, Độ âm điện giảm, Kim loại tăng, Phi kim giảm"], ["F có độ âm điện lớn nhất (3,98); Cs có tính kim loại mạnh nhất"], ["Bán kính nguyên tử giảm do điện tích hạt nhân tăng hút electron mạnh hơn."], "Trong nhóm IA, kim loại nào có tính khử mạnh nhất: Li, Na, K, Cs?", "Cs (Xesi) có tính khử mạnh nhất.", ["SODIUM", "POTASSIUM", "WATER"]),
        (7, 2, "Bài 7: Xu hướng biến đổi hợp chất trong một chu kì", "Biến đổi hóa trị cao nhất với oxi (từ I đến VII) và hóa trị với hydro (từ IV đến I). Tính axit-bazơ của oxit và hiđroxit.", ["Trong chu kì: Tính bazơ của oxit/hiđroxit giảm dần, tính axit tăng dần"], ["Na₂O (Bazơ mạnh) → Al₂O₃ (Lưỡng tính) → SiO₂ (Axit yếu) → SO₃ → Cl₂O₇ (Axit rất mạnh)"], ["Hiđroxit cao nhất của nhóm VIIA là HClO4 (axit cực mạnh)."], "Axit nào mạnh nhất trong dãy: H3PO4, H2SO4, HClO4?", "HClO4 là axit mạnh nhất.", ["SO2", "P2O5", "HCl"]),
